WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT s.id, s.customer_id, s.browser, s.country, (SELECT AVG(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS avg_order_amount FROM islands s ORDER BY country DESC
